import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`klaviyo-audit`,heroTitle:`Audit your Klaviyo account in minutes`,heroSubtitle:`Perplexity Computer reviews your flows, segments, and campaigns, and delivers a prioritized optimization plan — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Analyzing your Klaviyo flows, triggers, and automations`,`Benchmarking campaign performance against email marketing best practices`,`Identifying revenue leaks in segmentation and deliverability`,`Full audit with prioritized fixes and revenue opportunities — ready to implement`],generatingSteps:[`Connecting to your Klaviyo account to extract flows, segments, and campaign data`,`Designing an agent to benchmark your metrics and identify underperforming flows`,`Configuring segmentation analysis and deliverability checks across all active campaigns`,`Setting up your prioritized audit report with fix-by-fix revenue impact estimates`],featureSectionTitle:`From Klaviyo account to optimization playbook`,featureCardTitles:[`Connects to your email stack`,`Outputs you can implement`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Google Analytics, Shopify, Slack, Notion — Computer plugs into your tools so audit insights flow straight into your marketing workflow.`,`Flow-by-flow performance scorecards. Segment health reports. Deliverability diagnostics. A prioritized playbook with revenue impact estimates for every fix.`],capabilitySectionTitle:`Your email strategist, on autopilot`,capabilitySectionSubtitle:`Start an audit, step away, come back to a complete Klaviyo optimization plan.`,capabilityCards:[{title:`Flow Audit`,description:`Computer can review every active flow — welcome series, abandoned cart, post-purchase, winback — and flag missing steps, weak subject lines, and timing gaps.`},{title:`Segment Analysis`,description:`Computer can evaluate your segment structure — identifying overlap, underused behavioral triggers, and high-value cohorts you're not targeting.`},{title:`Campaign Benchmarking`,description:`Computer can score your open rates, click rates, and revenue per recipient against industry benchmarks — and pinpoint exactly where you're leaving money.`},{title:`Connect Your Tools`,description:`Computer can pull data from Google Analytics, Shopify, Google Sheets, Slack, and more — build workflows across your entire email and ecommerce stack.`},{title:`Track Progress`,description:`Computer can remember your past audit scores, flow configurations, and segment structures — so every re-audit measures real improvement over time.`},{title:`Monitor & Alert`,description:`Computer can watch your Klaviyo metrics weekly and flag deliverability drops, flow performance declines, or new optimization opportunities.`}]});export{t as default};
